7	    public class MigrateRepoCommandArgs : CommandArgs
8	    {
9	        public string GithubSourceOrg { get; set; }
10	        public string SourceRepo { get; set; }
11	        public string GithubTargetOrg { get; set; }
12	        public string TargetRepo { get; set; }
13	        public string TargetApiUrl { get; set; }
14	        public string GhesApiUrl { get; set; }
15	        [Secret]
16	        public string AzureStorageConnectionString { get; set; }
17	        public string AwsBucketName { get; set; }
18	        [Secret]
19	        public string AwsAccessKey { get; set; }
20	        [Secret]
21	        public string AwsSecretKey { get; set; }
22	        [Secret]
23	        public string AwsSessionToken { get; set; }
24	        public string AwsRegion { get; set; }
25	        public bool NoSslVerify { get; set; }
26	        public string GitArchiveUrl { get; set; }
27	        public string MetadataArchiveUrl { get; set; }
28	        public bool SkipReleases { get; set; }
29	        public bool LockSourceRepo { get; set; }
30	        public bool QueueOnly { get; set; }
31	        public string TargetRepoVisibility { get; set; }
32	        [Secret]
33	        public string GithubSourcePat { get; set; }
34	        [Secret]
35	        public string GithubTargetPat { get; set; }
36	        public bool KeepArchive { get; set; }
37	        public bool UseGithubStorage { get; set; }
38	
39	        public override void Validate(OctoLogger log)
40	        {
41	            DefaultSourcePat(log);
42	            DefaultTargetRepo(log);
43	
44	            if (string.IsNullOrWhiteSpace(GitArchiveUrl) != string.IsNullOrWhiteSpace(MetadataArchiveUrl))
45	            {
46	                throw new OctoshiftCliException("When using archive urls, you must provide both --git-archive-url --metadata-archive-url");
47	            }
48	
49	            if (GhesApiUrl.IsNullOrWhiteSpace())
50	            {
51	                if (AwsBucketName.HasValue())
52	                {
53	                    throw new OctoshiftCliException("--ghes-api-url must be specified when --aws-bucket-name is specified.");
54	                }
55	
56	                if (NoSslVerify)
57	                {
58	                    throw new OctoshiftCliException("--ghes-api-url must be specified when --no-ssl-verify is specified.");
59	                }
60	
61	                if (KeepArchive)
62	                {
63	                    throw new OctoshiftCliException("--ghes-api-url must be specified when --keep-archive is specified.");
64	                }
65	                if (UseGithubStorage)
66	                {
67	                    throw new OctoshiftCliException("--ghes-api-url must be specified when --use-github-storage is specified.");
68	                }
69	            }
70	
71	            if (AwsBucketName.HasValue() && UseGithubStorage)
72	            {
73	                throw new OctoshiftCliException("The --use-github-storage flag was provided with an AWS S3 Bucket name. Archive cannot be uploaded to both locations.");
74	            }
75	
76	            if (AzureStorageConnectionString.HasValue() && UseGithubStorage)
77	            {
78	                throw new OctoshiftCliException("The --use-github-storage flag was provided with a connection string for an Azure storage account. Archive cannot be uploaded to both locations.");
79	            }
80	        }
81	
82	        private void DefaultTargetRepo(OctoLogger log)
83	        {
84	            if (TargetRepo.IsNullOrWhiteSpace())
85	            {
86	                log?.LogInformation($"Target repo name not provided, defaulting to same as source repo ({SourceRepo})");
87	                TargetRepo = SourceRepo;
88	            }
89	        }
90	
91	        private void DefaultSourcePat(OctoLogger log)
92	        {
93	            if (GithubTargetPat.HasValue() && GithubSourcePat.IsNullOrWhiteSpace())
94	            {
95	                GithubSourcePat = GithubTargetPat;
96	                log?.LogInformation("Since github-target-pat is provided, github-source-pat will also use its value.");
97	            }
98	        }
99	    }
100	}
